[pscustomobject]@{services=@(Get-CimInstance Win32_Service | Where-Object {$_.Name -match '^(MSSQL|SQLAgent|SQLBrowser|WinRM)'} | Select-Object Name,State,StartMode); localdb_installed_versions=@(if(Test-Path 'HKLM:\SOFTWARE\Microsoft\Microsoft SQL Server Local DB\Installed Versions'){Get-ChildItem 'HKLM:\SOFTWARE\Microsoft\Microsoft SQL Server Local DB\Installed Versions' | Select-Object -ExpandProperty PSChildName})} | ConvertTo-Json -Depth 4
